26	GUARD_INTERVAL_S = float(os.environ.get("SWARM_GUARD_INTERVAL_S", "4"))   # was 2 s: one sweep per agent tab
27	#   every 2 s added to the sandbox CPU load (see docs/INTEGRATION.md)
28	MAX_ACTIONS_PER_ITEM = 4        # per browse: an item that keeps coming back after this many tries is left to the agent
29	CLASSIFY_TIMEOUT_S = 45
30	EVAL_TIMEOUT_S = 10            # a page script that does not answer (page frozen by a native dialog) is given up
