168	
169	def signature(item: dict) -> str:
170	    """Item identity across pages and tabs: its text without digits (codes, dates, counters change) and its buttons."""
171	    text = re.sub(r"\d+", "#", item.get("text", "").lower())
172	    text = re.sub(r"\s+", " ", text)[:1200]
173	    buttons = "|".join(re.sub(r"\d+", "#", b.get("label", "").lower()) + str(bool(b.get("away"))) for b in item.get("buttons") or [])
174	    return f"{item.get('kind')}:{text}:{buttons}:{len(item.get('fields') or [])}"
175	
176	
177	def cacheable_fill(decision: dict) -> bool:
178	    """A fill that only ticks boxes and moves sliders is the same every time (cache it); one that copies a displayed
179	    code is not."""
180	    values = [str(f.get("value", "")).strip().lower() for f in decision.get("fields") or [] if isinstance(f, dict)]
181	    return bool(values) and all(v in ("true", "false", "max", "100") for v in values)
182	
183	
184	def host(url: str) -> str:
185	    return urlparse(url or "").netloc
186	
187	
188	NOISE = ("cookie", "survey", "notice", "banner", "error")
189	
190	
191	def pick_button(decision: dict, item: dict) -> int | None:
192	    """The button to click: the model's choice, unless it is a link to another page (a decoy) and the item has exactly
193	    one other button that stays on the page (its x/close): then that one. Retry links of error pages may lead away."""
194	    index = decision.get("button")
195	    buttons = item.get("buttons") or []
196	    if not isinstance(index, int) or not 0 <= index < len(buttons):
197	        return None
198	    if buttons[index].get("away") and decision.get("kind") != "error":
199	        stay = [b["i"] for b in buttons if not b.get("away")]
200	        return stay[0] if len(stay) == 1 else None
201	    return index
202	
203	
204	def safe_then_click(decision: dict, item: dict) -> str:
205	    """The confirm button to press after filling a gate, unless it leads to another page. A sandbox run: after passing
206	    the mail gate the guard pressed 'Original öffnen' (a link away, to a decoy page) on every sweep and the TAN lookup
207	    kept landing there; navigating is the agent's decision."""
208	    label = " ".join(str(decision.get("then_click") or "").split()).casefold()
209	    if not label:
210	        return ""
211	    for button in item.get("buttons") or []:
212	        if " ".join(str(button.get("label") or "").split()).casefold() == label and button.get("away"):
213	            return ""
214	    return str(decision.get("then_click"))
215	
216	
217	def allowed(decision: dict, item: dict, careful: bool) -> bool:
218	    """What the guard may do with `item`: in careful mode only clicks on noise that has no input fields."""
219	    action = decision.get("action")
220	    if action == "click":
221	        if pick_button(decision, item) is None:
222	            return False
223	        return not careful or (decision.get("kind") in NOISE and not item.get("fields"))
224	    if action == "fill":
225	        return not careful and bool(decision.get("fields") or decision.get("then_click"))
226	    return False
