229	class PopupGuard:
230	    """One per browse(): `sweep(evaluate)` clears the page once; `loop(evaluate)` sweeps until cancelled.
231	    `evaluate(js, *args)` runs a JS arrow function in the agent's current page."""
232	
233	    def __init__(self, ctx, author: str, careful: bool = False, fill=None):
234	        """`fill(pairs, then_click, item_id)` sets fields inside the observed gate only."""
235	        self.ctx, self.author, self.careful = ctx, author, careful
236	        self._fill = fill
237	        self._fresh: dict = {}             # decisions that are not cached (fills copying a code): used once
238	        self._lock = asyncio.Lock()
239	        self._tries: dict[str, int] = {}
240	        self.actions = 0
241	
242	    async def fill(self, evaluate, pairs: list[tuple[str, str]], then_click: str, item_id: int) -> str:
243	        if self._fill is not None:
244	            return await self._fill(pairs, then_click, item_id)
245	        from swarm.forms import fill_fields, scoped_evaluator
246	        return await fill_fields(scoped_evaluator(evaluate, item_id), pairs, "", then_click)
247	
248	    def _decide(self, site: str, items: list[dict]) -> dict[int, dict]:
249	        """Decisions for the scanned items that are known now (cached, or just classified for this guard). Unknown
250	        items are sent to the model in the background (one call per new item kind across all agents) and handled by
251	        a later sweep: a sweep never waits for the model, so the agent's step is never held up by it."""
252	        out, unknown = {}, []
253	        for item in items:
254	            key = (site, signature(item))
255	            if key in _DECISIONS:
256	                out[item["id"]] = _DECISIONS[key]
257	            elif key in self._fresh:
258	                observed, decision = self._fresh.pop(key)
259	                if observed == item.get("text"):
260	                    out[item["id"]] = decision
261	            elif key not in _PENDING:
262	                unknown.append((key, item))
263	        if unknown:
264	            for key, _ in unknown:
265	                _PENDING[key] = True
266	            task = asyncio.create_task(self._classify(site, unknown))
267	            _TASKS.add(task)                    # finishes even after this browse ended: other agents use the answer
268	            task.add_done_callback(_TASKS.discard)
269	        return out
270	
271	    async def _classify(self, site: str, unknown: list[tuple]) -> None:
272	        try:
273	            shown = [{k: item[k] for k in ("id", "kind", "text", "buttons", "fields")} for _, item in unknown]
274	            reply = await asyncio.wait_for(
275	                self.ctx.llm.ask_json(SYSTEM, json.dumps({"items": shown}, ensure_ascii=False)), CLASSIFY_TIMEOUT_S)
276	            by_id = {d.get("id"): d for d in (reply or {}).get("items") or [] if isinstance(d, dict)}
277	            for key, item in unknown:
278	                decision = by_id.get(item["id"]) or {"action": "leave", "kind": "other"}
279	                if decision.get("action") != "fill" or cacheable_fill(decision):
280	                    _DECISIONS[key] = decision      # a fill that copies a displayed code: asked again each time
281	                else:
282	                    self._fresh[key] = (item.get("text"), decision)
283	                log.info("guard %s: %s %s -> %s %s", site, item["kind"], item["text"][:80], decision.get("action"),
284	                         decision.get("kind"))
285	        except Exception as error:              # model slow or failing: the agent handles these items itself
286	            log.debug("guard classification failed: %s", error)
287	        finally:
288	            for key, _ in unknown:
289	                _PENDING.pop(key, None)
290	
291	
292	    async def sweep(self, evaluate) -> int:
293	        """Clear the current page once; returns how many items were handled."""
294	        if self._lock.locked():                 # a sweep is running: wait for it instead of starting another
295	            async with self._lock:
296	                return 0
297	        async with self._lock:
298	            try:
299	                scan = await asyncio.wait_for(evaluate(SCAN_JS), EVAL_TIMEOUT_S)
300	            except Exception:                   # page navigating / closed / frozen by a native dialog
301	                return 0
302	            items = (scan or {}).get("items") or [] if isinstance(scan, dict) else []
303	            if not items:
304	                return 0
305	            site = host(scan.get("url", ""))
306	            decisions = self._decide(site, items)
307	            handled = 0
308	            for item in items:
309	                decision = decisions.get(item["id"]) or {}
310	                sig = str(scan.get("url", "")) + "|" + signature(item)
311	                if decision.get("action") == "fill" and not cacheable_fill(decision):
312	                    sig += "|" + str(item.get("text", ""))
313	                if not allowed(decision, item, self.careful) or self._tries.get(sig, 0) >= MAX_ACTIONS_PER_ITEM:
314	                    continue
315	                self._tries[sig] = self._tries.get(sig, 0) + 1
316	                try:
317	                    if decision["action"] == "click":
318	                        button = pick_button(decision, item)
319	                        result = await asyncio.wait_for(evaluate(CLICK_JS, {"id": item["id"], "button": button,
320	                                                                          "allow_navigation": decision.get("kind") == "error"}),
321	                                                        EVAL_TIMEOUT_S)
322	                        label = item["buttons"][button]["label"]
323	                    else:
324	                        pairs = [(str(f.get("field", "")), str(f.get("value", ""))) for f in decision.get("fields") or []
325	                                 if isinstance(f, dict)]
326	                        then_click = safe_then_click(decision, item)
327	                        result = await asyncio.wait_for(self.fill(evaluate, pairs, then_click, item["id"]),
328	                                                        3 * EVAL_TIMEOUT_S)
329	                        label = then_click or "fields"
330	                except Exception as error:      # the item went away meanwhile
331	                    log.debug("guard action failed: %s", error)
332	                    continue
333	                handled += 1
334	                self.actions += 1
335	                log.info("guard %s [%s]: %s '%s' on %s: %s", site, self.author, decision["action"], label,
336	                         decision.get("kind"), str(result)[:120].replace("\n", "; "))
337	                await asyncio.sleep(0.6)        # let the page react before the agent reads it
338	            return handled
339	
340	    async def loop(self, evaluate, interval: float = GUARD_INTERVAL_S) -> None:
341	        while True:
342	            await asyncio.sleep(interval)
343	            try:
344	                await self.sweep(evaluate)
345	            except asyncio.CancelledError:
346	                raise
347	            except Exception as error:
348	                log.debug("guard sweep failed: %s", error)
