                               "instructions": f"Which website is the {description}? Use the brief and observations."}
    if not questions or not decide.available():
        return {}
    try:
        answers = await asyncio.wait_for(decide.decide({"brief": ctx.brief[:8000], "sites": sites,
                                                        "observations": observations}, questions, retries=1), 60)
    except Exception as error:  # noqa: BLE001 - Clef down: Qwen maps all roles
        log.info("clef role mapping failed: %s", error)
        return {}
    out = {}
    for role in questions:
        site_id, p = decide.picked(answers.get(role))
        if site_id in questions[role]["criteria"] and p >= CLEF_MIN:
            out[role] = site_id
    return out


