# the full SCAN_JS only when it moved, or on a new document (fresh) - real-time detection without screenshots.
# The observer callback only queues the changed nodes (no style or layout reads while the page or browser-use is
# working); they are checked here, at poll time, at most MAX per poll.
WATCH_JS = r"""() => {
  const w = window, MAX = 60;
  const BLOCK = 'dialog,[role=dialog],[role=alertdialog],[aria-modal=true],input[type=range],[role=slider]';
  const W = () => w.innerWidth || 1280, H = () => w.innerHeight || 800;
  const blocking = (el, added) => {
    if (!el || el.nodeType !== 1 || !el.isConnected || /^(browser-use|playwright)/i.test(el.id || '')) return false;
    if (el.matches(BLOCK) || (added && (el.tagName === 'IFRAME' || el.querySelector(BLOCK + ',iframe')))) return true;
    let s; try { s = getComputedStyle(el); } catch (e) { return false; }
    if (s.position !== 'fixed' && s.position !== 'sticky') return false;
    const r = el.getBoundingClientRect();
    return r.width * r.height >= 0.03 * W() * H() && s.display !== 'none' && s.visibility !== 'hidden';
  };
  let state = w.__swarmWatch, fresh = false;
  if (!state) {
    state = w.__swarmWatch = {seq: 1, queue: new Map()};
    fresh = true;
    new MutationObserver(list => {
      if (state.queue.size > 400) return;
      for (const m of list) {
        if (m.type === 'attributes') { if (!state.queue.has(m.target)) state.queue.set(m.target, false); }
        else for (const n of m.addedNodes) if (n.nodeType === 1) state.queue.set(n, true);
      }
    }).observe(document.documentElement, {subtree: true, childList: true, attributes: true,
                                          attributeFilter: ['class', 'style', 'open', 'hidden', 'aria-hidden']});
  }
  if (state.queue.size) {
    let hit = state.queue.size > 400, n = 0;
    for (const [el, added] of state.queue) { if (hit || ++n > MAX) break; hit = blocking(el, added); }
    state.queue.clear();
    if (hit) state.seq++;
  }
  return {seq: state.seq, fresh};
}"""

